'use server';
/**
 * @fileOverview A flow for creating virtual bank accounts.
 *
 * - createVirtualAccount - A function that handles the virtual account creation process.
 * - CreateVirtualAccountInput - The input type for the createVirtualAccount function.
 * - CreateVirtualAccountOutput - The return type for the createVirtualAccount function.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { User } from '@/lib/data';

// Simulates a bank's naming convention for accounts
const generateAccountName = (firstName: string, lastName: string) => {
  return `${firstName} ${lastName} - ZuriPay`;
};

// Simulates generating a NUBAN (Nigerian Uniform Bank Account Number)
const generateNuban = () => {
  return Math.floor(1_000_000_000 + Math.random() * 9_000_000_000).toString();
};

const CreateVirtualAccountInputSchema = z.object({
  userId: z.string().describe('The unique ID of the user creating the account.'),
  firstName: z.string().describe("The user's first name."),
  lastName: z.string().describe("The user's last name."),
});
export type CreateVirtualAccountInput = z.infer<typeof CreateVirtualAccountInputSchema>;

const CreateVirtualAccountOutputSchema = z.object({
  accountNumber: z.string().describe('The newly generated 10-digit bank account number.'),
  accountName: z.string().describe('The name associated with the new account.'),
  bankName: z.string().describe('The name of the bank holding the account.'),
  currency: z.string().describe('The currency of the account.'),
});
export type CreateVirtualAccountOutput = z.infer<typeof CreateVirtualAccountOutputSchema>;


const createVirtualAccountFlow = ai.defineFlow(
  {
    name: 'createVirtualAccountFlow',
    inputSchema: CreateVirtualAccountInputSchema,
    outputSchema: CreateVirtualAccountOutputSchema,
  },
  async (input) => {
    // In a real-world scenario, this would involve calling a banking API provider.
    // For this simulation, we will generate the details.
    const accountName = generateAccountName(input.firstName, input.lastName);
    const accountNumber = generateNuban();
    const bankName = 'ZuriPay Bank';
    const currency = 'NGN';

    return {
      accountName,
      accountNumber,
      bankName,
      currency,
    };
  }
);

// This is the wrapper function that client components will call.
export async function createVirtualAccount(input: CreateVirtualAccountInput): Promise<CreateVirtualAccountOutput> {
  return createVirtualAccountFlow(input);
}
