import { notFound } from 'next/navigation';
import AboutPage from '@/components/pages/about-page';
import AccountPage from '@/components/pages/account-page';
import AdminPage from '@/components/pages/admin-page';
import AuthPage from '@/components/pages/auth-page';
import BlogPage from '@/components/pages/blog-page';
import NewPostPage from '@/components/pages/blog-new-page';
import CareersPage from '@/components/pages/careers-page';
import ContactPage from '@/components/pages/contact-page';
import DevelopersPage from '@/components/pages/developers-page';
import OnboardingGuidePage from '@/components/pages/developers-onboarding-guide-page';
import SandboxPage from '@/components/pages/developers-sandbox-page';
import PrivacyPolicyPage from '@/components/pages/privacy-policy-page';
import ServicesPage from '@/components/pages/services-page';
import BusinessBankingPage from '@/components/pages/services-business-banking-page';
import CardIssuingPage from '@/components/pages/services-card-issuing-page';
import CrossBorderTransfersPage from '@/components/pages/services-cross-border-transfers-page';
import MerchantPaymentsPage from '@/components/pages/services-merchant-payments-page';
import VirtualAccountsPage from '@/components/pages/services-virtual-accounts-page';
import TermsOfServicePage from '@/components/pages/terms-of-service-page';
import WalletPage from '@/components/pages/wallet-page';

const pageComponents: { [key: string]: React.ComponentType } = {
  about: AboutPage,
  account: AccountPage,
  admin: AdminPage,
  auth: AuthPage,
  blog: BlogPage,
  'blog/new': NewPostPage,
  careers: CareersPage,
  contact: ContactPage,
  developers: DevelopersPage,
  'developers/onboarding-guide': OnboardingGuidePage,
  'developers/sandbox': SandboxPage,
  'privacy-policy': PrivacyPolicyPage,
  services: ServicesPage,
  'services/business-banking': BusinessBankingPage,
  'services/card-issuing': CardIssuingPage,
  'services/cross-border-transfers': CrossBorderTransfersPage,
  'services/merchant-payments': MerchantPaymentsPage,
  'services/virtual-accounts': VirtualAccountsPage,
  'terms-of-service': TermsOfServicePage,
  wallet: WalletPage,
};

export default function Page({ params }: { params: { slug: string[] } }) {
  const path = params.slug.join('/');
  const Component = pageComponents[path];

  if (!Component) {
    notFound();
  }

  return <Component />;
}
